import{randomUUID}from'node:crypto';import{Router,type NextFunction,type Request,type Response}from'express';import{z}from'zod';import{db}from'../database/db.js';import{runtimeMetrics}from'../observability.js';import{hashPassword,hashToken}from'../security.js';import{calculateSalePoints,reconcileSalePoints}from'../loyalty.js';import{encryptSecret}from'../bling.js';import{nextOperationRun}from'../operation-schedules.js';
export const platformAdminRoutes=Router();
function auth(req:Request,res:Response,next:NextFunction){const token=req.cookies?.fideliza_platform_session,row=token&&db.prepare(`SELECT pa.id adminId,pa.name,pa.email,pa.role FROM platform_sessions ps JOIN platform_admins pa ON pa.id=ps.admin_id WHERE ps.token_hash=? AND ps.expires_at>datetime('now') AND pa.active=1`).get(hashToken(token));if(!row)return res.status(401).json({error:'Administrador não autenticado'});(req as any).platformAuth=row;next()}
function audit(req:Request,action:string,type:string,id?:string,metadata:unknown={}){db.prepare('INSERT INTO platform_audit_logs(id,admin_id,action,entity_type,entity_id,ip,metadata)VALUES(?,?,?,?,?,?,?)').run(randomUUID(),(req as any).platformAuth.adminId,action,type,id||null,req.ip||null,JSON.stringify(metadata))}
const companySql=`SELECT t.id,t.name,t.slug,t.legal_name legalName,t.cnpj,t.email,t.phone,t.website,t.address,t.city,t.state,t.postal_code postalCode,t.responsible_name responsibleName,t.created_at createdAt,t.login_blocked loginBlocked,t.customer_portal_enabled customerPortalEnabled,t.suspension_reason suspensionReason,t.suspended_at suspendedAt,s.plan_code planCode,s.status,s.monthly_price_cents monthlyPriceCents,s.current_period_end currentPeriodEnd,s.payment_method paymentMethod,s.billing_day billingDay,COALESCE(s.joined_at,s.created_at) joinedAt,p.user_limit userLimit,p.consumer_limit consumerLimit,(SELECT COUNT(*) FROM users WHERE tenant_id=t.id) users,(SELECT COUNT(*) FROM users WHERE tenant_id=t.id AND active=1) activeUsers,(SELECT COUNT(*) FROM customers WHERE tenant_id=t.id AND deleted_at IS NULL AND enrolled_at IS NOT NULL AND cpf IS NOT NULL AND length(trim(name))>=2 AND length(COALESCE(phone,''))>=10) customers,(SELECT COUNT(*) FROM customers WHERE tenant_id=t.id AND deleted_at IS NULL AND enrolled_at IS NOT NULL AND cpf IS NOT NULL AND length(trim(name))>=2 AND length(COALESCE(phone,''))>=10 AND COALESCE(updated_at,created_at)>=datetime('now','-30 days')) activeConsumers FROM tenants t LEFT JOIN subscriptions s ON s.tenant_id=t.id LEFT JOIN platform_plans p ON p.code=s.plan_code`;
platformAdminRoutes.get('/platform/dashboard',auth,(_q,res)=>{const s=db.prepare(`SELECT COUNT(*) total,SUM(status='active') active,SUM(status='trialing') trialing,SUM(status='suspended') suspended,SUM(status='past_due') pastDue,SUM(status='canceled') canceled,COALESCE(SUM(CASE WHEN status='active' THEN monthly_price_cents ELSE 0 END),0)mrr,SUM(CASE WHEN current_period_end IS NOT NULL AND date(current_period_end)<=date('now','+7 days') THEN 1 ELSE 0 END)dueSoon FROM subscriptions`).get()as any,c=db.prepare(`SELECT COUNT(*)total,SUM(COALESCE(updated_at,created_at)>=datetime('now','-30 days'))active30 FROM customers WHERE deleted_at IS NULL AND enrolled_at IS NOT NULL AND cpf IS NOT NULL AND length(trim(name))>=2 AND length(COALESCE(phone,''))>=10`).get()as any,j=db.prepare(`SELECT SUM(status='completed')completed,SUM(status='failed')failed,SUM(status IN ('queued','processing'))pending FROM jobs`).get()as any,r=runtimeMetrics(),ie=Number((db.prepare("SELECT COUNT(*)c FROM integration_connections WHERE status!='connected'").get()as any).c)+Number((db.prepare("SELECT COUNT(*)c FROM erp_connectors WHERE status='error' OR last_error IS NOT NULL").get()as any).c),tenants=Number((db.prepare('SELECT COUNT(*)c FROM tenants').get()as any).c),today=Number((db.prepare("SELECT COUNT(DISTINCT user_id)c FROM sessions WHERE created_at>=date('now')").get()as any).c),created=Number((db.prepare("SELECT COUNT(*)c FROM customers WHERE created_at>=date('now') AND deleted_at IS NULL AND enrolled_at IS NOT NULL AND cpf IS NOT NULL AND length(COALESCE(phone,''))>=10").get()as any).c),active=Number(s.active||0),trials=Number(s.trialing||0),incidents=db.prepare("SELECT * FROM platform_incidents WHERE status!='resolved' ORDER BY started_at DESC LIMIT 5").all();res.json({kpis:{tenants,activeSubscriptions:active+trials,mrrCents:Number(s.mrr||0),consumers:Number(c.total||0)},business:{tenants,active,trialing:trials,suspended:Number(s.suspended||0),mrrCents:Number(s.mrr||0),arrCents:Number(s.mrr||0)*12,churnRate:s.total?Number((Number(s.canceled||0)/s.total*100).toFixed(1)):0,trialConversion:active+trials?Number((active/(active+trials)*100).toFixed(1)):0,consumers:Number(c.total||0),activeConsumers30:Number(c.active30||0)},operational:{usersToday:today,createdToday:created,processes:Number(j.completed||0),pendingProcesses:Number(j.pending||0),failedProcesses:Number(j.failed||0),integrationErrors:ie,averageResponseMs:r.averageResponseMs,uptimeSeconds:r.uptimeSeconds,availability:r.requests?Number(((1-r.errors/r.requests)*100).toFixed(2)):100},alerts:[{type:'warning',label:'Vencimentos em 7 dias',value:Number(s.dueSoon||0)},{type:'danger',label:'Assinaturas inadimplentes',value:Number(s.pastDue||0)},{type:'danger',label:'Integrações com erro',value:ie},{type:'info',label:'Incidentes em aberto',value:incidents.length}],incidents})});
platformAdminRoutes.get('/platform/overview',auth,(_q,res)=>{const companies=db.prepare(`${companySql} ORDER BY t.created_at DESC`).all(),users=db.prepare(`SELECT u.id,u.name,u.email,u.role,u.active,u.two_factor_enabled twoFactorEnabled,u.mfa_required mfaRequired,u.last_login_at lastLoginAt,t.name companyName FROM users u JOIN tenants t ON t.id=u.tenant_id ORDER BY u.created_at DESC`).all(),plans=db.prepare('SELECT code,name,monthly_price_cents monthlyPriceCents,user_limit userLimit,consumer_limit consumerLimit,storage_mb storageMb,features,active FROM platform_plans ORDER BY monthly_price_cents').all().map((p:any)=>({...p,features:JSON.parse(p.features)})),finance={gateway:{provider:'asaas',configured:Boolean(process.env.ASAAS_API_KEY),environment:process.env.ASAAS_ENVIRONMENT==='production'?'production':'sandbox'},summary:db.prepare(`SELECT COALESCE(SUM(CASE WHEN status='paid'THEN amount_cents ELSE 0 END),0)accumulatedRevenueCents,COALESCE(SUM(CASE WHEN status='pending'THEN amount_cents ELSE 0 END),0)pendingCents,COALESCE(SUM(CASE WHEN status='overdue'THEN amount_cents ELSE 0 END),0)overdueCents FROM invoices`).get(),invoices:db.prepare(`SELECT i.id,t.name companyName,i.amount_cents amountCents,i.status,i.due_at dueAt,i.paid_at paidAt,i.payment_method paymentMethod,i.boleto_url boletoUrl,i.invoice_pdf_url invoicePdfUrl,i.notified_at notifiedAt,i.gateway,i.external_payment_id externalPaymentId,i.external_status externalStatus,i.invoice_url invoiceUrl,i.bank_slip_url bankSlipUrl,i.last_synced_at lastSyncedAt,(SELECT MAX(f.created_at) FROM billing_followups f WHERE f.invoice_id=i.id) lastFollowUpAt,(SELECT MIN(f.next_action_at) FROM billing_followups f WHERE f.invoice_id=i.id AND f.status='open' AND f.next_action_at IS NOT NULL) nextFollowUpAt FROM invoices i JOIN tenants t ON t.id=i.tenant_id ORDER BY i.due_at DESC`).all(),byPlan:db.prepare(`SELECT p.name plan,COUNT(s.id)subscriptions,COALESCE(SUM(CASE WHEN s.status='active'THEN s.monthly_price_cents ELSE 0 END),0)revenueCents FROM platform_plans p LEFT JOIN subscriptions s ON s.plan_code=p.code GROUP BY p.code`).all()},monitoring={runtime:runtimeMetrics(),queues:db.prepare('SELECT status,COUNT(*)count FROM jobs GROUP BY status').all(),integrations:db.prepare(`SELECT t.name companyName,c.provider,c.status,c.last_sync_at lastSyncAt FROM integration_connections c JOIN tenants t ON t.id=c.tenant_id`).all(),incidents:db.prepare('SELECT * FROM platform_incidents ORDER BY started_at DESC').all()},audit=db.prepare(`SELECT l.id,a.name actor,l.action,l.entity_type entityType,l.entity_id entityId,l.ip,l.created_at createdAt FROM platform_audit_logs l LEFT JOIN platform_admins a ON a.id=l.admin_id ORDER BY l.created_at DESC LIMIT 200`).all(),support=db.prepare(`SELECT s.id,t.name companyName,s.subject,s.description,s.status,s.priority,s.source,s.category,s.customer_id customerId,c.name customerName,c.cpf customerCpf,s.assigned_to assignedTo,s.sla_due_at slaDueAt,s.created_at createdAt,s.updated_at updatedAt FROM support_tickets s LEFT JOIN tenants t ON t.id=s.tenant_id LEFT JOIN customers c ON c.id=s.customer_id ORDER BY CASE s.status WHEN 'open' THEN 1 WHEN 'in_progress' THEN 2 WHEN 'waiting_customer' THEN 3 ELSE 4 END,s.created_at DESC`).all(),settings=Object.fromEntries((db.prepare('SELECT key,value FROM global_settings').all()as any[]).map(x=>[x.key,x.value]));res.json({companies,users,plans,finance,monitoring,audit,support,settings})});
platformAdminRoutes.patch('/platform/companies/:id',auth,(req,res)=>{const p=z.object({name:z.string().min(2),legalName:z.string().optional(),cnpj:z.string().optional(),email:z.string().optional(),phone:z.string().optional(),responsibleName:z.string().optional(),loginBlocked:z.boolean()}).parse(req.body);db.prepare('UPDATE tenants SET name=?,legal_name=?,cnpj=?,email=?,phone=?,responsible_name=?,login_blocked=? WHERE id=?').run(p.name,p.legalName||null,p.cnpj||null,p.email||null,p.phone||null,p.responsibleName||null,p.loginBlocked?1:0,String(req.params.id));res.status(204).end()});
platformAdminRoutes.patch('/platform/companies/:id/customer-portal',auth,(req,res)=>{const enabled=z.object({enabled:z.boolean()}).parse(req.body).enabled,id=String(req.params.id),result=db.prepare('UPDATE tenants SET customer_portal_enabled=? WHERE id=?').run(enabled?1:0,id);if(!result.changes)return res.status(404).json({error:'Empresa não encontrada'});if(!enabled)db.prepare('DELETE FROM customer_sessions WHERE account_id IN (SELECT id FROM customer_accounts WHERE tenant_id=?)').run(id);audit(req,'customer_portal.update','tenant',id,{enabled});res.status(204).end()});
platformAdminRoutes.patch('/platform/users/:id',auth,(req,res)=>{const p=z.object({role:z.enum(['owner','manager','operator']),active:z.boolean(),mfaRequired:z.boolean()}).parse(req.body),id=String(req.params.id),user=db.prepare('SELECT two_factor_enabled FROM users WHERE id=?').get(id)as any;if(!user)return res.status(404).json({error:'Usuário não encontrado'});if(p.mfaRequired&&!user.two_factor_enabled)return res.status(409).json({error:'O usuário precisa configurar o autenticador antes de tornar o MFA obrigatório'});db.prepare('UPDATE users SET role=?,active=?,mfa_required=? WHERE id=?').run(p.role,p.active?1:0,p.mfaRequired?1:0,id);if(!p.active)db.prepare('DELETE FROM sessions WHERE user_id=?').run(id);res.status(204).end()});
platformAdminRoutes.patch('/platform/plans/:code',auth,(req,res)=>{const p=z.object({name:z.string().min(2),monthlyPriceCents:z.number().int().min(0),userLimit:z.number().int().positive(),consumerLimit:z.number().int().positive(),storageMb:z.number().int().positive(),active:z.boolean(),features:z.array(z.string().min(1).max(80)).max(100).optional()}).parse(req.body),code=String(req.params.code),current=db.prepare('SELECT code FROM platform_plans WHERE code=?').get(code);if(!current)return res.status(404).json({error:'Plano não encontrado'});db.prepare('UPDATE platform_plans SET name=?,monthly_price_cents=?,user_limit=?,consumer_limit=?,storage_mb=?,features=COALESCE(?,features),active=?,updated_at=CURRENT_TIMESTAMP WHERE code=?').run(p.name,p.monthlyPriceCents,p.userLimit,p.consumerLimit,p.storageMb,p.features?JSON.stringify([...new Set(p.features)]):null,p.active?1:0,code);audit(req,'plan.update','plan',code,p);res.status(204).end()});
platformAdminRoutes.patch('/platform/settings',auth,(req,res)=>{const p=z.record(z.string(),z.string().max(2000)).parse(req.body),up=db.prepare('INSERT INTO global_settings(key,value,updated_by)VALUES(?,?,?) ON CONFLICT(key)DO UPDATE SET value=excluded.value,updated_by=excluded.updated_by,updated_at=CURRENT_TIMESTAMP');db.transaction(()=>Object.entries(p).forEach(([k,v])=>up.run(k,v,(req as any).platformAuth.adminId)))();audit(req,'settings.update','settings',undefined,{keys:Object.keys(p)});res.status(204).end()});
platformAdminRoutes.get('/platform/cnpj/:cnpj',auth,async(req,res)=>{const cnpj=String(req.params.cnpj).replace(/\D/g,'');if(cnpj.length!==14)return res.status(400).json({error:'Informe um CNPJ com 14 dígitos'});try{const response=await fetch(`https://brasilapi.com.br/api/cnpj/v1/${cnpj}`,{headers:{accept:'application/json','user-agent':'FidelizaPlus/1.0'},signal:AbortSignal.timeout(8000)});if(response.status===404)return res.status(404).json({error:'CNPJ não encontrado'});if(!response.ok)throw new Error(String(response.status));const x=await response.json()as any;res.json({cnpj,name:x.nome_fantasia||x.razao_social,legalName:x.razao_social,email:String(x.email||'').toLowerCase(),phone:x.ddd_telefone_1||x.ddd_telefone_2||'',address:[x.descricao_tipo_de_logradouro,x.logradouro,x.numero,x.complemento,x.bairro].filter(Boolean).join(' '),city:x.municipio||'',state:x.uf||'',postalCode:x.cep||'',segment:x.cnae_fiscal_descricao||'',status:x.descricao_situacao_cadastral||''})}catch{res.status(502).json({error:'BrasilAPI indisponível. Tente novamente ou preencha manualmente.'})}});
platformAdminRoutes.post('/platform/companies',auth,(req,res)=>{const p=z.object({name:z.string().min(2),legalName:z.string().min(2),cnpj:z.string().min(14),email:z.string().email(),phone:z.string().min(8),responsibleName:z.string().min(2),planCode:z.string(),paymentMethod:z.enum(['boleto','pix','card']),billingDay:z.number().int().min(1).max(28),adminName:z.string().min(2),adminEmail:z.string().email(),adminPassword:z.string().min(10)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Revise os dados obrigatórios da empresa'});try{const id=db.transaction(()=>{const tenantId=randomUUID(),slug=p.data.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'-'+Math.random().toString(36).slice(2,6);db.prepare('INSERT INTO tenants(id,name,slug,legal_name,cnpj,email,phone,responsible_name,segment)VALUES(?,?,?,?,?,?,?,?,?)').run(tenantId,p.data.name,slug,p.data.legalName,p.data.cnpj.replace(/\D/g,''),p.data.email,p.data.phone,p.data.responsibleName,'');const plan=db.prepare('SELECT monthly_price_cents FROM platform_plans WHERE code=? AND active=1').get(p.data.planCode)as any;if(!plan)throw new Error('PLAN');db.prepare("INSERT INTO subscriptions(id,tenant_id,plan_code,status,monthly_price_cents,current_period_start,current_period_end,joined_at,payment_method,billing_day,gateway)VALUES(?,?,?,'trialing',?,CURRENT_TIMESTAMP,date('now','+30 days'),CURRENT_TIMESTAMP,?,?,'asaas')").run(randomUUID(),tenantId,p.data.planCode,plan.monthly_price_cents,p.data.paymentMethod,p.data.billingDay);db.prepare("INSERT INTO users(id,tenant_id,name,email,password_hash,role,source)VALUES(?,?,?,?,?,'owner','platform')").run(randomUUID(),tenantId,p.data.adminName,p.data.adminEmail,hashPassword(p.data.adminPassword));return tenantId})();audit(req,'create','tenant',id,{plan:p.data.planCode,paymentMethod:p.data.paymentMethod});res.status(201).json({id})}catch(e){res.status(409).json({error:(e as Error).message==='PLAN'?'Plano inicial inválido':'CNPJ ou e-mail já cadastrado'})}});
platformAdminRoutes.get('/platform/companies/:id/detail',auth,(req,res)=>{const id=String(req.params.id),company=db.prepare(`${companySql} WHERE t.id=?`).get(id);if(!company)return res.status(404).json({error:'Empresa não encontrada'});const users=db.prepare('SELECT id,name,email,cpf,phone,job_title jobTitle,role,active,mfa_required mfaRequired,two_factor_enabled mfaEnabled,last_login_at lastLoginAt,blocked_reason blockedReason FROM users WHERE tenant_id=? ORDER BY name').all(id),customers=db.prepare(`SELECT c.id,c.name,c.cpf,c.email,c.phone,c.status,c.points_balance pointsBalance,c.enrolled_at enrolledAt,(SELECT MAX(s.occurred_at) FROM sales s WHERE s.customer_id=c.id AND s.tenant_id=c.tenant_id AND s.reversed_at IS NULL) lastPurchaseAt,c.created_at createdAt,ca.active accessActive,ca.last_login_at lastLoginAt,(SELECT COUNT(*) FROM sales s WHERE s.customer_id=c.id AND s.tenant_id=c.tenant_id AND s.reversed_at IS NULL) purchases FROM customers c LEFT JOIN customer_accounts ca ON ca.customer_id=c.id AND ca.tenant_id=c.tenant_id WHERE c.tenant_id=? AND c.deleted_at IS NULL ORDER BY c.created_at DESC LIMIT 500`).all(id),accessLogs=db.prepare(`SELECT id,user_type userType,user_id userId,success,ip,user_agent userAgent,reason,created_at createdAt FROM platform_access_logs WHERE tenant_id=? ORDER BY created_at DESC LIMIT 200`).all(id);res.json({company,users,customers,consumers:{total:customers.length,active:(customers as any[]).filter(x=>x.status==='active').length,withAccess:(customers as any[]).filter(x=>x.accessActive).length},invoices:db.prepare('SELECT id,amount_cents amountCents,status,due_at dueAt,paid_at paidAt,payment_method paymentMethod,boleto_url boletoUrl,invoice_pdf_url invoicePdfUrl,invoice_url invoiceUrl,bank_slip_url bankSlipUrl,external_payment_id externalPaymentId,external_status externalStatus,notified_at notifiedAt FROM invoices WHERE tenant_id=? ORDER BY due_at DESC').all(id),billingEvents:db.prepare('SELECT invoice_id invoiceId,event_type eventType,description,metadata,created_at createdAt FROM billing_events WHERE tenant_id=? ORDER BY created_at DESC LIMIT 100').all(id),accessLogs,audit:db.prepare("SELECT action,metadata,created_at createdAt FROM platform_audit_logs WHERE entity_type='tenant' AND entity_id=? ORDER BY created_at DESC").all(id),integrations:db.prepare('SELECT provider,status,last_sync_at lastSyncAt FROM integration_connections WHERE tenant_id=?').all(id)})});
platformAdminRoutes.patch('/platform/companies/:id/profile',auth,(req,res)=>{const id=String(req.params.id),p=z.object({name:z.string().trim().min(2).max(160),legalName:z.string().trim().min(2).max(200),cnpj:z.string().transform(v=>v.replace(/\D/g,'')).refine(v=>v.length===14),email:z.string().email(),phone:z.string().trim().min(8).max(30),responsibleName:z.string().trim().min(2).max(160),website:z.string().url().or(z.literal('')),address:z.string().max(300),city:z.string().max(120),state:z.string().max(2),postalCode:z.string().max(12)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Revise os dados cadastrais obrigatórios'});const before=db.prepare('SELECT * FROM tenants WHERE id=?').get(id);if(!before)return res.status(404).json({error:'Empresa não encontrada'});try{db.prepare('UPDATE tenants SET name=?,legal_name=?,cnpj=?,email=?,phone=?,responsible_name=?,website=?,address=?,city=?,state=?,postal_code=? WHERE id=?').run(p.data.name,p.data.legalName,p.data.cnpj,p.data.email,p.data.phone,p.data.responsibleName,p.data.website||null,p.data.address||null,p.data.city||null,p.data.state.toUpperCase()||null,p.data.postalCode||null,id);audit(req,'company.update','tenant',id,{before,after:p.data});res.status(204).end()}catch{return res.status(409).json({error:'CNPJ ou e-mail já cadastrado em outra empresa'})}});
platformAdminRoutes.post('/platform/companies/:id/users/:userId/reset-password',auth,(req,res)=>{const tenantId=String(req.params.id),userId=String(req.params.userId),p=z.object({temporaryPassword:z.string().min(12).regex(/[A-Z]/).regex(/[a-z]/).regex(/[0-9]/).regex(/[^A-Za-z0-9]/)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Use uma senha temporária com 12 caracteres, maiúscula, minúscula, número e símbolo'});const user=db.prepare('SELECT id,name,email,role FROM users WHERE id=? AND tenant_id=?').get(userId,tenantId)as any;if(!user)return res.status(404).json({error:'Usuário da empresa não encontrado'});db.transaction(()=>{db.prepare('UPDATE users SET password_hash=?,active=1,blocked_reason=NULL,blocked_at=NULL WHERE id=? AND tenant_id=?').run(hashPassword(p.data.temporaryPassword),userId,tenantId);db.prepare('DELETE FROM sessions WHERE user_id=?').run(userId);db.prepare('UPDATE password_reset_tokens SET used_at=CURRENT_TIMESTAMP WHERE user_id=? AND used_at IS NULL').run(userId)})();audit(req,'company_user.password_reset','tenant',tenantId,{userId,userEmail:user.email,role:user.role});res.status(204).end()});
platformAdminRoutes.patch('/platform/subscriptions/:tenantId',auth,(req,res)=>{const tenantId=String(req.params.tenantId),p=z.object({planCode:z.string().min(1).max(60),status:z.enum(['trialing','active','past_due','suspended','canceled']),monthlyPriceCents:z.number().int().min(0),currentPeriodEnd:z.string().regex(/^\d{4}-\d{2}-\d{2}$/),paymentMethod:z.enum(['boleto','pix','card']).optional(),billingDay:z.number().int().min(1).max(28).optional()}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Revise plano, vigência e condições da assinatura'});if(!db.prepare('SELECT id FROM tenants WHERE id=?').get(tenantId))return res.status(404).json({error:'Empresa não encontrada'});const current=db.prepare('SELECT * FROM subscriptions WHERE tenant_id=?').get(tenantId)as any,plan=db.prepare('SELECT code FROM platform_plans WHERE code=?').get(p.data.planCode);if(!plan)return res.status(400).json({error:'Plano informado não existe'});const paymentMethod=p.data.paymentMethod||current?.payment_method||'boleto',billingDay=p.data.billingDay||current?.billing_day||10;db.transaction(()=>{if(current)db.prepare('UPDATE subscriptions SET plan_code=?,status=?,monthly_price_cents=?,current_period_end=?,payment_method=?,billing_day=?,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=?').run(p.data.planCode,p.data.status,p.data.monthlyPriceCents,p.data.currentPeriodEnd,paymentMethod,billingDay,tenantId);else db.prepare('INSERT INTO subscriptions(id,tenant_id,plan_code,status,monthly_price_cents,current_period_start,current_period_end,joined_at,payment_method,billing_day,gateway)VALUES(?,?,?,?,?,CURRENT_TIMESTAMP,?,CURRENT_TIMESTAMP,?,?,\'asaas\')').run(randomUUID(),tenantId,p.data.planCode,p.data.status,p.data.monthlyPriceCents,p.data.currentPeriodEnd,paymentMethod,billingDay);db.prepare("INSERT INTO billing_events(id,tenant_id,event_type,description,metadata)VALUES(?,?, 'subscription.updated','Condições comerciais da assinatura atualizadas',?)").run(randomUUID(),tenantId,JSON.stringify({before:current?{planCode:current.plan_code,status:current.status,monthlyPriceCents:current.monthly_price_cents,currentPeriodEnd:current.current_period_end,paymentMethod:current.payment_method,billingDay:current.billing_day}:null,after:{...p.data,paymentMethod,billingDay}}))})();audit(req,'subscription.update','tenant',tenantId,{...p.data,paymentMethod,billingDay});res.status(204).end()});
