platformAdminRoutes.post('/platform/support/tickets/:id/reprocess-sale',auth,(req,res)=>{const p=z.object({orderNumber:z.string().min(1).max(80)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Informe o número do pedido'});const id=String(req.params.id),ticket=db.prepare('SELECT * FROM support_tickets WHERE id=?').get(id)as any;if(!ticket?.customer_id)return res.status(409).json({error:'Chamado sem cliente vinculado'});const sale=db.prepare('SELECT * FROM sales WHERE tenant_id=? AND customer_id=? AND order_number=?').get(ticket.tenant_id,ticket.customer_id,p.data.orderNumber)as any;if(!sale)return res.status(404).json({error:'Pedido não encontrado para este cliente'});const desired=sale.reversed_at?0:calculateSalePoints(ticket.tenant_id,sale.total_cents,sale.occurred_at).points,result=db.transaction(()=>{const reconciliation=reconcileSalePoints(ticket.tenant_id,ticket.customer_id,sale.id,desired,`Reprocessamento administrativo do pedido ${p.data.orderNumber}`);db.prepare("INSERT INTO support_ticket_events(id,ticket_id,tenant_id,actor_type,actor_id,action,message,metadata)VALUES(?,?,?,?,?,'sale_reprocessed',?,?)").run(randomUUID(),id,ticket.tenant_id,'platform_admin',(req as any).platformAuth.adminId,`Pedido ${p.data.orderNumber} reprocessado`,JSON.stringify(reconciliation));db.prepare("UPDATE support_tickets SET status='in_progress',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(id);return reconciliation})();audit(req,'support.sale_reprocessed','support_ticket',id,{orderNumber:p.data.orderNumber,...result});res.json(result)});
