platformAdminRoutes.get('/platform/plans/overview',auth,(_req,res)=>{const plans=(db.prepare(`SELECT p.code,p.name,p.monthly_price_cents monthlyPriceCents,p.user_limit userLimit,p.consumer_limit consumerLimit,p.storage_mb storageMb,p.features,p.active,COUNT(s.id) subscriptions,SUM(CASE WHEN s.status='active' THEN 1 ELSE 0 END) activeSubscriptions,SUM(CASE WHEN s.status='trialing' THEN 1 ELSE 0 END) trials,COALESCE(SUM(CASE WHEN s.status='active' THEN s.monthly_price_cents ELSE 0 END),0) mrrCents FROM platform_plans p LEFT JOIN subscriptions s ON s.plan_code=p.code GROUP BY p.code ORDER BY p.monthly_price_cents`).all()as any[]).map(x=>({...x,features:JSON.parse(x.features||'[]')})),companies=db.prepare(`SELECT t.id tenantId,t.name companyName,s.plan_code planCode,p.name planName,s.status,s.monthly_price_cents monthlyPriceCents,s.current_period_end currentPeriodEnd,p.user_limit userLimit,p.consumer_limit consumerLimit,p.storage_mb storageMb,(SELECT COUNT(*) FROM users u WHERE u.tenant_id=t.id AND u.active=1) users,(SELECT COUNT(*) FROM customers c WHERE c.tenant_id=t.id AND c.deleted_at IS NULL) consumers FROM tenants t JOIN subscriptions s ON s.tenant_id=t.id JOIN platform_plans p ON p.code=s.plan_code ORDER BY t.name`).all()as any[],addons=(db.prepare(`SELECT a.id,a.code,a.name,a.description,a.monthly_price_cents monthlyPriceCents,a.additional_users additionalUsers,a.additional_consumers additionalConsumers,a.additional_storage_mb additionalStorageMb,a.compatible_plans compatiblePlans,a.active,a.created_at createdAt,COUNT(aa.id) assignments,COALESCE(SUM(CASE WHEN aa.status='active' THEN aa.monthly_price_cents*aa.quantity ELSE 0 END),0) mrrCents FROM plan_addons a LEFT JOIN plan_addon_assignments aa ON aa.addon_id=a.id GROUP BY a.id ORDER BY a.active DESC,a.name`).all()as any[]).map(x=>({...x,compatiblePlans:JSON.parse(x.compatiblePlans||'[]')})),trialPolicies=(db.prepare(`SELECT id,name,plan_code planCode,duration_days durationDays,extension_days extensionDays,auto_convert autoConvert,requires_payment_method requiresPaymentMethod,conversion_plan_code conversionPlanCode,communication_days communicationDays,active,created_at createdAt FROM plan_trial_policies ORDER BY active DESC,created_at DESC`).all()as any[]).map(x=>({...x,communicationDays:JSON.parse(x.communicationDays||'[]')})),commercialRules=db.prepare(`SELECT id,name,rule_type ruleType,source_plan_code sourcePlanCode,target_plan_code targetPlanCode,discount_percent discountPercent,approval_required approvalRequired,notice_days noticeDays,valid_from validFrom,valid_until validUntil,active,created_at createdAt FROM plan_commercial_rules ORDER BY active DESC,created_at DESC`).all(),changeRequests=db.prepare(`SELECT r.id,r.tenant_id tenantId,t.name companyName,r.from_plan_code fromPlanCode,pf.name fromPlanName,r.to_plan_code toPlanCode,pt.name toPlanName,r.status,r.reason,r.admin_notes adminNotes,r.created_at createdAt,r.reviewed_at reviewedAt FROM plan_change_requests r JOIN tenants t ON t.id=r.tenant_id LEFT JOIN platform_plans pf ON pf.code=r.from_plan_code JOIN platform_plans pt ON pt.code=r.to_plan_code ORDER BY CASE r.status WHEN 'pending' THEN 1 ELSE 2 END,r.created_at DESC LIMIT 100`).all()as any[],activeCompanies=companies.filter(x=>x.status==='active'),trials=companies.filter(x=>x.status==='trialing'),mrrCents=activeCompanies.reduce((n,x)=>n+Number(x.monthlyPriceCents||0),0),capacityRisks=companies.filter(x=>x.users/Math.max(1,x.userLimit)>=.8||x.consumers/Math.max(1,x.consumerLimit)>=.8).length;res.json({summary:{plans:plans.length,activePlans:plans.filter(x=>x.active).length,activeSubscriptions:activeCompanies.length,trials:trials.length,mrrCents,pendingChanges:changeRequests.filter(x=>x.status==='pending').length,capacityRisks,addonMrrCents:addons.reduce((n,x)=>n+Number(x.mrrCents||0),0)},plans,companies,addons,trialPolicies,commercialRules,changeRequests})});
