platformAdminRoutes.get('/platform/plan-change-requests',auth,(_req,res)=>res.json(db.prepare(`SELECT r.id,r.tenant_id tenantId,t.name companyName,r.from_plan_code fromPlanCode,pf.name fromPlanName,r.to_plan_code toPlanCode,pt.name toPlanName,r.status,r.reason,r.admin_notes adminNotes,r.created_at createdAt,r.reviewed_at reviewedAt,a.name reviewedBy FROM plan_change_requests r JOIN tenants t ON t.id=r.tenant_id LEFT JOIN platform_plans pf ON pf.code=r.from_plan_code JOIN platform_plans pt ON pt.code=r.to_plan_code LEFT JOIN platform_admins a ON a.id=r.reviewed_by ORDER BY CASE r.status WHEN 'pending' THEN 1 ELSE 2 END,r.created_at DESC`).all()));
platformAdminRoutes.patch('/platform/plan-change-requests/:id',auth,(req,res)=>{const p=z.object({decision:z.enum(['approved','rejected']),adminNotes:z.string().min(3).max(1000)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Informe a decisão e a justificativa'});const id=String(req.params.id),change=db.prepare("SELECT * FROM plan_change_requests WHERE id=? AND status='pending'").get(id)as any;if(!change)return res.status(404).json({error:'Solicitação pendente não encontrada'});const plan=db.prepare('SELECT * FROM platform_plans WHERE code=? AND active=1').get(change.to_plan_code)as any;if(!plan)return res.status(409).json({error:'O plano solicitado não está disponível'});db.transaction(()=>{db.prepare('UPDATE plan_change_requests SET status=?,admin_notes=?,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=?').run(p.data.decision,p.data.adminNotes,(req as any).platformAuth.adminId,id);if(p.data.decision==='approved'){db.prepare(`INSERT INTO subscriptions(id,tenant_id,plan_code,status,monthly_price_cents,current_period_start,current_period_end) VALUES(?,?,?,'active',?,CURRENT_TIMESTAMP,date('now','+30 days')) ON CONFLICT(tenant_id) DO UPDATE SET plan_code=excluded.plan_code,monthly_price_cents=excluded.monthly_price_cents,updated_at=CURRENT_TIMESTAMP`).run(randomUUID(),change.tenant_id,plan.code,plan.monthly_price_cents);db.prepare("INSERT INTO billing_events(id,tenant_id,event_type,description,metadata)VALUES(?,?,'plan.changed','Plano da assinatura alterado',?)").run(randomUUID(),change.tenant_id,JSON.stringify({requestId:id,from:change.from_plan_code,to:change.to_plan_code,monthlyPriceCents:plan.monthly_price_cents}));}})();audit(req,`plan_change.${p.data.decision}`,'plan_change_request',id,{tenantId:change.tenant_id,toPlanCode:change.to_plan_code,notes:p.data.adminNotes});res.json({ok:true,status:p.data.decision})});
