platformAdminRoutes.get('/platform/system',auth,(_req,res)=>{
  const jobs=db.prepare(`SELECT j.id,t.id tenantId,t.name companyName,j.type,j.status,j.attempts,j.error,j.result,j.created_at createdAt,j.started_at startedAt,j.completed_at completedAt FROM jobs j JOIN tenants t ON t.id=j.tenant_id ORDER BY j.created_at DESC LIMIT 500`).all();
  const connectors=db.prepare(`SELECT e.id,t.id tenantId,t.name companyName,e.name,e.provider,e.connection_type connectionType,e.status,e.capabilities,e.last_test_at lastTestAt,e.last_sync_at lastSyncAt,e.last_error lastError,'erp' kind FROM erp_connectors e JOIN tenants t ON t.id=e.tenant_id UNION ALL SELECT c.id,t.id,t.name,c.provider,c.provider,'oauth',c.status,'[]',NULL,c.last_sync_at,c.last_error,'oauth' FROM integration_connections c JOIN tenants t ON t.id=c.tenant_id ORDER BY companyName`).all();
  const apiKeys=db.prepare(`SELECT k.id,k.name,k.key_prefix keyPrefix,k.scopes,k.active,k.last_used_at lastUsedAt,k.expires_at expiresAt,k.created_at createdAt,t.id tenantId,t.name companyName FROM api_keys k JOIN tenants t ON t.id=k.tenant_id ORDER BY k.created_at DESC`).all();
  const loginAttempts=db.prepare('SELECT id,email,success,ip,created_at createdAt FROM platform_login_attempts ORDER BY created_at DESC LIMIT 300').all();
  const accessLogs=db.prepare(`SELECT l.id,l.user_type userType,l.user_id userId,l.success,l.ip,l.user_agent userAgent,l.reason,l.created_at createdAt,t.name companyName FROM platform_access_logs l LEFT JOIN tenants t ON t.id=l.tenant_id ORDER BY l.created_at DESC LIMIT 500`).all();
  const sessions=db.prepare(`SELECT s.id,u.name,u.email,t.name companyName,'company' userType,s.created_at createdAt,s.expires_at expiresAt FROM sessions s JOIN users u ON u.id=s.user_id JOIN tenants t ON t.id=u.tenant_id UNION ALL SELECT s.id,c.name,c.email,t.name,'customer',s.created_at,s.expires_at FROM customer_sessions s JOIN customer_accounts a ON a.id=s.account_id JOIN customers c ON c.id=a.customer_id JOIN tenants t ON t.id=a.tenant_id UNION ALL SELECT s.id,a.name,a.email,'Fideliza Plus','platform',s.created_at,s.expires_at FROM platform_sessions s JOIN platform_admins a ON a.id=s.admin_id ORDER BY createdAt DESC LIMIT 400`).all();
  const webhooks=db.prepare(`SELECT w.id,t.id tenantId,t.name companyName,w.provider,w.event_type eventType,w.status,w.attempts,w.last_error lastError,w.occurred_at occurredAt,w.processed_at processedAt,w.created_at createdAt FROM integration_webhook_events w JOIN tenants t ON t.id=w.tenant_id ORDER BY w.created_at DESC LIMIT 400`).all();
  const outbound=db.prepare(`SELECT o.id,t.name companyName,o.recipient,o.channel,o.template,o.subject,o.status,o.attempts,o.error,o.scheduled_at scheduledAt,o.sent_at sentAt,o.created_at createdAt FROM outbound_messages o LEFT JOIN tenants t ON t.id=o.tenant_id ORDER BY o.created_at DESC LIMIT 300`).all();
  const auditLogs=db.prepare(`SELECT l.id,a.name actor,l.action,l.entity_type entityType,l.entity_id entityId,l.ip,l.metadata,l.created_at createdAt FROM platform_audit_logs l LEFT JOIN platform_admins a ON a.id=l.admin_id ORDER BY l.created_at DESC LIMIT 500`).all();
  const permissions=db.prepare('SELECT role,permission,enabled,description,updated_at updatedAt FROM platform_permissions ORDER BY role,permission').all();
  const identities=db.prepare(`SELECT (SELECT COUNT(*) FROM platform_admins WHERE active=1) platformAdmins,(SELECT COUNT(*) FROM users WHERE active=1) companyUsers,(SELECT COUNT(*) FROM customer_accounts WHERE active=1) customers,(SELECT COUNT(*) FROM users WHERE active=1 AND two_factor_enabled=1) mfaEnabled,(SELECT COUNT(*) FROM users WHERE active=1 AND mfa_required=1) mfaRequired`).get();
  const database={pageCount:Number(db.pragma('page_count',{simple:true})),pageSize:Number(db.pragma('page_size',{simple:true})),freePages:Number(db.pragma('freelist_count',{simple:true})),journalMode:String(db.pragma('journal_mode',{simple:true})),integrity:String(db.pragma('quick_check',{simple:true})),tables:Number((db.prepare("SELECT COUNT(*) count FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'").get()as any).count)};
  const settings=Object.fromEntries((db.prepare('SELECT key,value FROM global_settings').all()as any[]).map(x=>[x.key,x.value]));
  const tenants=db.prepare('SELECT id,name FROM tenants ORDER BY name').all();
  const incidents=db.prepare('SELECT * FROM platform_incidents ORDER BY started_at DESC LIMIT 100').all();
  res.json({jobs,connectors,apiKeys,loginAttempts,accessLogs,sessions,webhooks,outbound,auditLogs,permissions,identities,database,settings,tenants,incidents,runtime:runtimeMetrics()});
});
