const operationTimezone=z.string().min(3).max(80).refine(value=>{try{new Intl.DateTimeFormat('pt-BR',{timeZone:value});return true}catch{return false}});
function operationDataset(dataset:string,tenantId:string){if(dataset==='companies')return db.prepare(`SELECT id,name,slug,cnpj,email,created_at criado_em FROM tenants WHERE (?='' OR id=?) ORDER BY name`).all(tenantId,tenantId)as any[];if(dataset==='users')return db.prepare(`SELECT t.name empresa,u.name nome,u.email,u.role perfil,u.active ativo,u.last_login_at ultimo_acesso FROM users u JOIN tenants t ON t.id=u.tenant_id WHERE (?='' OR t.id=?) ORDER BY t.name,u.name`).all(tenantId,tenantId)as any[];if(dataset==='audit')return db.prepare(`SELECT t.name empresa,a.action acao,a.entity_type entidade,a.entity_id referencia,a.created_at criado_em FROM audit_logs a JOIN tenants t ON t.id=a.tenant_id WHERE (?='' OR t.id=?) ORDER BY a.created_at DESC LIMIT 10000`).all(tenantId,tenantId)as any[];return db.prepare(`SELECT t.name empresa,j.id,j.type tipo,j.status,j.attempts tentativas,j.error,j.created_at criado_em,j.completed_at concluido_em FROM jobs j JOIN tenants t ON t.id=j.tenant_id WHERE (?='' OR t.id=?) ORDER BY j.created_at DESC LIMIT 10000`).all(tenantId,tenantId)as any[]}
platformAdminRoutes.get('/platform/operations/overview',auth,(req,res)=>{const tenantId=String(req.query.tenantId||''),days=Math.min(365,Math.max(1,Number(req.query.days)||30)),jobs=(db.prepare(`SELECT j.id,j.tenant_id tenantId,t.name companyName,j.type,j.status,j.attempts,j.priority,j.error,j.result,j.dead_lettered_at deadLetteredAt,j.created_at createdAt,j.started_at startedAt,j.completed_at completedAt,CASE WHEN j.started_at IS NOT NULL THEN CAST((julianday(COALESCE(j.completed_at,CURRENT_TIMESTAMP))-julianday(j.started_at))*86400000 AS INTEGER) END durationMs FROM jobs j JOIN tenants t ON t.id=j.tenant_id WHERE j.created_at>=datetime('now',?) AND (?='' OR j.tenant_id=?) ORDER BY j.created_at DESC LIMIT 1000`).all(`-${days} days`,tenantId,tenantId)as any[]).map(x=>({...x,result:jsonValue(x.result,null)})),queues=db.prepare(`SELECT p.job_type jobType,p.display_name displayName,p.paused,p.concurrency,p.max_attempts maxAttempts,p.retention_days retentionDays,p.updated_at updatedAt,SUM(CASE WHEN j.status='queued' THEN 1 ELSE 0 END) queued,SUM(CASE WHEN j.status='processing' THEN 1 ELSE 0 END) processing,SUM(CASE WHEN j.status='completed' AND j.created_at>=datetime('now',?) THEN 1 ELSE 0 END) completed,SUM(CASE WHEN j.status='failed' AND j.created_at>=datetime('now',?) THEN 1 ELSE 0 END) failed,SUM(CASE WHEN j.dead_lettered_at IS NOT NULL THEN 1 ELSE 0 END) deadLetter FROM platform_queue_policies p LEFT JOIN jobs j ON j.type=p.job_type AND (?='' OR j.tenant_id=?) GROUP BY p.job_type ORDER BY p.display_name`).all(`-${days} days`,`-${days} days`,tenantId,tenantId),exports=(db.prepare(`SELECT e.id,e.tenant_id tenantId,t.name companyName,e.dataset,e.format,e.status,e.filters,e.row_count rowCount,e.error,e.expires_at expiresAt,e.created_at createdAt,e.downloaded_at downloadedAt FROM platform_operation_exports e LEFT JOIN tenants t ON t.id=e.tenant_id WHERE (?='' OR COALESCE(e.tenant_id,'')=?) ORDER BY e.created_at DESC LIMIT 200`).all(tenantId,tenantId)as any[]).map(x=>({...x,filters:jsonValue(x.filters,{})})),schedules=db.prepare(`SELECT s.id,s.tenant_id tenantId,t.name companyName,s.name,s.job_type jobType,s.frequency,s.run_at runAt,s.timezone,s.active,s.last_run_at lastRunAt,s.next_run_at nextRunAt,s.last_status lastStatus,s.last_error lastError,s.created_at createdAt FROM platform_operation_schedules s JOIN tenants t ON t.id=s.tenant_id WHERE (?='' OR s.tenant_id=?) ORDER BY s.active DESC,s.next_run_at`).all(tenantId,tenantId),completed=jobs.filter(x=>x.status==='completed'),failed=jobs.filter(x=>x.status==='failed'),durations=completed.map(x=>Number(x.durationMs||0)).filter(Boolean);res.json({period:{days},summary:{jobs:jobs.length,queued:jobs.filter(x=>x.status==='queued').length,processing:jobs.filter(x=>x.status==='processing').length,completed:completed.length,failed:failed.length,successRate:completed.length+failed.length?Number((completed.length/(completed.length+failed.length)*100).toFixed(1)):100,averageDurationMs:durations.length?Math.round(durations.reduce((n,x)=>n+x,0)/durations.length):0,deadLetter:jobs.filter(x=>x.deadLetteredAt).length},jobs,queues,exports,schedules,companyOptions:db.prepare('SELECT id,name FROM tenants ORDER BY name').all()})});
platformAdminRoutes.post('/platform/operations/jobs',auth,(req,res)=>{const p=z.object({tenantId:z.string().min(1),type:operationJobType,payload:z.string().max(5_000_000).optional(),priority:z.number().int().min(1).max(10).default(5)}).safeParse(req.body);if(!p.success||((p.data?.type==='import_customers'||p.data?.type==='import_sales')&&!p.data.payload))return res.status(400).json({error:'Informe empresa, tipo, prioridade e conteúdo para importações'});if(!db.prepare('SELECT 1 FROM tenants WHERE id=?').get(p.data.tenantId))return res.status(404).json({error:'Empresa não encontrada'});const id=randomUUID();db.prepare('INSERT INTO jobs(id,tenant_id,type,payload,priority)VALUES(?,?,?,?,?)').run(id,p.data.tenantId,p.data.type,p.data.payload||null,p.data.priority);audit(req,'operation.job.enqueue','job',id,{tenantId:p.data.tenantId,type:p.data.type,priority:p.data.priority});res.status(202).json({id,status:'queued'})});
platformAdminRoutes.patch('/platform/operations/queues/:type',auth,(req,res)=>{const type=operationJobType.safeParse(req.params.type),p=z.object({paused:z.boolean(),concurrency:z.number().int().min(1).max(20),maxAttempts:z.number().int().min(1).max(20),retentionDays:z.number().int().min(1).max(365)}).safeParse(req.body);if(!type.success||!p.success)return res.status(400).json({error:'Revise fila, concorrência, tentativas e retenção'});db.prepare('UPDATE platform_queue_policies SET paused=?,concurrency=?,max_attempts=?,retention_days=?,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE job_type=?').run(p.data.paused?1:0,p.data.concurrency,p.data.maxAttempts,p.data.retentionDays,(req as any).platformAuth.adminId,type.data);audit(req,'operation.queue.update','queue_policy',type.data,p.data);res.status(204).end()});
platformAdminRoutes.post('/platform/operations/exports',auth,(req,res)=>{const p=z.object({tenantId:z.string().nullable().optional(),dataset:z.enum(['companies','users','jobs','audit']),format:z.literal('csv'),expiresInDays:z.number().int().min(1).max(30)}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Revise conjunto de dados, formato e validade'});const rows=operationDataset(p.data.dataset,p.data.tenantId||''),id=randomUUID(),expires=new Date(Date.now()+p.data.expiresInDays*86400000).toISOString();db.prepare("INSERT INTO platform_operation_exports(id,tenant_id,dataset,format,status,row_count,expires_at,created_by)VALUES(?,?,?,?, 'ready',?,?,?)").run(id,p.data.tenantId||null,p.data.dataset,p.data.format,rows.length,expires,(req as any).platformAuth.adminId);audit(req,'operation.export.create','operation_export',id,{dataset:p.data.dataset,tenantId:p.data.tenantId||null,rows:rows.length});res.status(201).json({id,rowCount:rows.length})});
platformAdminRoutes.get('/platform/operations/exports/:id/download',auth,(req,res)=>{const id=String(req.params.id),record=db.prepare("SELECT * FROM platform_operation_exports WHERE id=? AND status='ready' AND expires_at>CURRENT_TIMESTAMP").get(id)as any;if(!record)return res.status(404).json({error:'Exportação indisponível ou expirada'});const rows=operationDataset(record.dataset,record.tenant_id||''),cols=rows.length?Object.keys(rows[0]):['sem_dados'],esc=(v:unknown)=>`"${String(v??'').replaceAll('"','""')}"`;db.prepare('UPDATE platform_operation_exports SET downloaded_at=CURRENT_TIMESTAMP WHERE id=?').run(id);audit(req,'operation.export.download','operation_export',id,{rows:rows.length});res.type('text/csv').setHeader('Content-Disposition',`attachment; filename=fideliza-${record.dataset}-${id}.csv`);res.send(`\uFEFF${cols.join(';')}\n${rows.map(row=>cols.map(c=>esc(row[c])).join(';')).join('\n')}`)});
platformAdminRoutes.post('/platform/operations/schedules',auth,(req,res)=>{const p=z.object({tenantId:z.string().min(1),name:z.string().min(3).max(120),jobType:z.enum(['refresh_gie','sync_bling']),frequency:z.enum(['hourly','daily','weekly']),runAt:z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/),timezone:operationTimezone}).safeParse(req.body);if(!p.success)return res.status(400).json({error:'Revise empresa, rotina, frequência, horário e fuso'});if(!db.prepare('SELECT 1 FROM tenants WHERE id=?').get(p.data.tenantId))return res.status(404).json({error:'Empresa não encontrada'});const id=randomUUID();db.prepare('INSERT INTO platform_operation_schedules(id,tenant_id,name,job_type,frequency,run_at,timezone,next_run_at,created_by)VALUES(?,?,?,?,?,?,?,?,?)').run(id,p.data.tenantId,p.data.name,p.data.jobType,p.data.frequency,p.data.runAt,p.data.timezone,nextOperationRun(p.data.frequency,p.data.runAt,p.data.timezone),(req as any).platformAuth.adminId);audit(req,'operation.schedule.create','operation_schedule',id,p.data);res.status(201).json({id})});
platformAdminRoutes.patch('/platform/operations/schedules/:id',auth,(req,res)=>{const active=z.object({active:z.boolean()}).safeParse(req.body),id=String(req.params.id);if(!active.success)return res.status(400).json({error:'Informe a situação do agendamento'});const result=db.prepare('UPDATE platform_operation_schedules SET active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(active.data.active?1:0,id);if(!result.changes)return res.status(404).json({error:'Agendamento não encontrado'});audit(req,'operation.schedule.status','operation_schedule',id,active.data);res.status(204).end()});
platformAdminRoutes.post('/platform/operations/schedules/:id/run',auth,(req,res)=>{const id=String(req.params.id),s=db.prepare('SELECT * FROM platform_operation_schedules WHERE id=?').get(id)as any;if(!s)return res.status(404).json({error:'Agendamento não encontrado'});const jobId=randomUUID();db.transaction(()=>{db.prepare('INSERT INTO jobs(id,tenant_id,type,payload,priority)VALUES(?,?,?,?,7)').run(jobId,s.tenant_id,s.job_type,s.payload||null);db.prepare("UPDATE platform_operation_schedules SET last_run_at=CURRENT_TIMESTAMP,last_status='queued',last_error=NULL,next_run_at=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").run(nextOperationRun(s.frequency,s.run_at,s.timezone),id)})();audit(req,'operation.schedule.run','operation_schedule',id,{jobId});res.status(202).json({jobId,status:'queued'})});
platformAdminRoutes.post('/platform/webhooks/:id/retry',auth,(req,res)=>{const id=String(req.params.id),result=db.prepare("UPDATE integration_webhook_events SET status='accepted',processed_at=NULL,last_error=NULL,attempts=0 WHERE id=? AND status IN ('failed','error')").run(id);if(!result.changes)return res.status(409).json({error:'Somente webhooks com falha podem ser reenfileirados'});audit(req,'webhook.retry','webhook',id,{});res.status(202).json({id,status:'accepted'})});
platformAdminRoutes.get('/platform/users/global',auth,(_req,res)=>{const staff=db.prepare(`SELECT u.id,u.name,u.email,u.role,u.active,u.mfa_required mfaRequired,u.two_factor_enabled mfaEnabled,u.last_login_at lastLoginAt,u.blocked_reason blockedReason,u.source,t.name companyName,'company' userType FROM users u JOIN tenants t ON t.id=u.tenant_id`).all(),consumers=db.prepare(`SELECT ca.id,c.name,c.email,'customer' role,ca.active,0 mfaRequired,0 mfaEnabled,ca.last_login_at lastLoginAt,NULL blockedReason,'customer_portal' source,t.name companyName,'customer' userType FROM customer_accounts ca JOIN customers c ON c.id=ca.customer_id JOIN tenants t ON t.id=ca.tenant_id`).all(),accessLogs=db.prepare('SELECT * FROM platform_access_logs ORDER BY created_at DESC LIMIT 300').all(),permissions=db.prepare('SELECT * FROM platform_permissions ORDER BY role,permission').all();res.json({users:[...staff,...consumers],accessLogs,permissions})});
platformAdminRoutes.patch('/platform/permissions/:role/:permission',auth,(req,res)=>{const enabled=z.object({enabled:z.boolean()}).parse(req.body).enabled;db.prepare('UPDATE platform_permissions SET enabled=?,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE role=? AND permission=?').run(enabled?1:0,(req as any).platformAuth.adminId,String(req.params.role),String(req.params.permission));audit(req,'permission.update','permission',`${req.params.role}:${req.params.permission}`,{enabled});res.status(204).end()});
const moduleKey=z.string().regex(/^[a-z0-9_-]{2,40}$/),sectionKey=z.string().regex(/^[a-z0-9_-]{2,60}$/),recordBody=z.object({title:z.string().min(2).max(160),tenantId:z.string().min(3).max(80).nullable().optional(),status:z.enum(['draft','active','pending','paused','resolved','archived','error']).default('active'),priority:z.enum(['low','medium','high','critical']).default('medium'),owner:z.string().max(120).optional(),dueAt:z.string().nullable().optional(),payload:z.record(z.string(),z.unknown()).default({})});
platformAdminRoutes.get('/platform/modules/:module/:section',auth,(req,res)=>{const module=moduleKey.parse(req.params.module),section=sectionKey.parse(req.params.section),records=(db.prepare(`SELECT r.id,r.module,r.section,r.tenant_id tenantId,t.name companyName,r.title,r.status,r.priority,r.owner,r.due_at dueAt,r.payload,r.created_at createdAt,r.updated_at updatedAt FROM platform_module_records r LEFT JOIN tenants t ON t.id=r.tenant_id WHERE r.module=? AND r.section=? ORDER BY CASE r.priority WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'medium' THEN 3 ELSE 4 END,r.updated_at DESC`).all(module,section)as any[]).map(r=>({...r,payload:JSON.parse(r.payload||'{}')}));res.json({records,summary:{total:records.length,active:records.filter(r=>['active','pending'].includes(r.status)).length,critical:records.filter(r=>r.priority==='critical').length,overdue:records.filter(r=>r.dueAt&&new Date(r.dueAt)<new Date()&&!['resolved','archived'].includes(r.status)).length}})});
platformAdminRoutes.post('/platform/modules/:module/:section',auth,(req,res)=>{const module=moduleKey.parse(req.params.module),section=sectionKey.parse(req.params.section),p=recordBody.parse(req.body),id=randomUUID();db.prepare('INSERT INTO platform_module_records(id,module,section,tenant_id,title,status,priority,owner,due_at,payload,created_by)VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(id,module,section,p.tenantId||null,p.title,p.status,p.priority,p.owner||null,p.dueAt||null,JSON.stringify(p.payload),(req as any).platformAuth.adminId);db.prepare('INSERT INTO platform_configuration_history(id,module,section,record_id,admin_id,after_value)VALUES(?,?,?,?,?,?)').run(randomUUID(),module,section,id,(req as any).platformAuth.adminId,JSON.stringify(p));audit(req,'module.create',module,id,{section});res.status(201).json({id})});
platformAdminRoutes.patch('/platform/modules/:module/:section/:id',auth,(req,res)=>{const module=moduleKey.parse(req.params.module),section=sectionKey.parse(req.params.section),p=recordBody.parse(req.body),id=String(req.params.id),before=db.prepare('SELECT * FROM platform_module_records WHERE id=? AND module=? AND section=?').get(id,module,section);if(!before)return res.status(404).json({error:'Registro não encontrado'});db.prepare('UPDATE platform_module_records SET tenant_id=?,title=?,status=?,priority=?,owner=?,due_at=?,payload=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(p.tenantId||null,p.title,p.status,p.priority,p.owner||null,p.dueAt||null,JSON.stringify(p.payload),id);db.prepare('INSERT INTO platform_configuration_history(id,module,section,record_id,admin_id,before_value,after_value)VALUES(?,?,?,?,?,?,?)').run(randomUUID(),module,section,id,(req as any).platformAuth.adminId,JSON.stringify(before),JSON.stringify(p));audit(req,'module.update',module,id,{section});res.status(204).end()});
platformAdminRoutes.delete('/platform/modules/:module/:section/:id',auth,(req,res)=>{const module=moduleKey.parse(req.params.module),section=sectionKey.parse(req.params.section),id=String(req.params.id),before=db.prepare('SELECT * FROM platform_module_records WHERE id=? AND module=? AND section=?').get(id,module,section);if(!before)return res.status(404).json({error:'Registro não encontrado'});db.prepare('DELETE FROM platform_module_records WHERE id=?').run(id);db.prepare('INSERT INTO platform_configuration_history(id,module,section,record_id,admin_id,before_value)VALUES(?,?,?,?,?,?)').run(randomUUID(),module,section,id,(req as any).platformAuth.adminId,JSON.stringify(before));audit(req,'module.delete',module,id,{section});res.status(204).end()});
platformAdminRoutes.get('/platform/modules/:module/:section/export',auth,(req,res)=>{const module=moduleKey.parse(req.params.module),section=sectionKey.parse(req.params.section),rows=db.prepare(`SELECT r.title,t.name empresa,r.status,r.priority prioridade,r.owner responsavel,r.due_at prazo,r.payload,r.updated_at atualizado FROM platform_module_records r LEFT JOIN tenants t ON t.id=r.tenant_id WHERE r.module=? AND r.section=? ORDER BY r.updated_at DESC`).all(module,section)as any[],cols=['title','empresa','status','prioridade','responsavel','prazo','payload','atualizado'],esc=(v:unknown)=>`"${String(v??'').replaceAll('"','""')}"`;res.type('text/csv').setHeader('Content-Disposition',`attachment; filename=fideliza-${module}-${section}.csv`);res.send(`\uFEFF${cols.join(';')}\n${rows.map(row=>cols.map(c=>esc(row[c])).join(';')).join('\n')}`)});
platformAdminRoutes.get('/platform/reports/export',auth,(req,res)=>{const report=String(req.query.report||'companies'),rows:any[]=report==='users'?db.prepare(`SELECT t.name empresa,u.name,u.email,u.role perfil,u.active ativo,u.last_login_at ultimo_acesso FROM users u JOIN tenants t ON t.id=u.tenant_id`).all():report==='finance'?db.prepare(`SELECT t.name empresa,i.amount_cents valor_centavos,i.status,i.due_at vencimento,i.paid_at pagamento FROM invoices i JOIN tenants t ON t.id=i.tenant_id`).all():db.prepare(`${companySql} ORDER BY t.name`).all(),cols=rows.length?Object.keys(rows[0]):['sem_dados'],esc=(v:unknown)=>`"${String(v??'').replaceAll('"','""')}"`;res.type('text/csv').setHeader('Content-Disposition',`attachment; filename=fideliza-${report}.csv`);res.send(`\uFEFF${cols.join(';')}\n${rows.map(row=>cols.map(c=>esc(row[c])).join(';')).join('\n')}`)});
